[BEGIN]
module TopModule (
    input  wire clk,
    input  wire areset,
    input  wire train_valid,
    input  wire train_taken,
    output logic [1:0] state
);

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 2'b01;
        end else if (train_valid) begin
            if (train_taken) begin
                if (state != 2'b11)
                    state <= state + 1'b1;
            end else begin
                if (state != 2'b00)
                    state <= state - 1'b1;
            end
        end
    end

endmodule
[DONE]
